// ─── File: CrossPartnerPaymentDemo.java ───
// Cross-partner payment: in-flight state + bulkhead + breaker + idempotency + Saga + recon.
// Each class below would be its own file in a real project.
package com.bank.xpay;

import java.math.BigDecimal;
import java.util.logging.*;

public class CrossPartnerPaymentDemo {

    private static final Logger log = Logger.getLogger("XPay");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        // Two external partners: P1 healthy, P2 down for the first few calls then recovers.
        ExternalPartner p1 = new ExternalPartner("PARTNER-1", 0);   // never fails
        ExternalPartner p2 = new ExternalPartner("PARTNER-2", 3);   // fails first 3 calls
        PartnerChannel c1 = new PartnerChannel(p1);                 // bulkhead + breaker each
        PartnerChannel c2 = new PartnerChannel(p2);

        PaymentSaga saga = new PaymentSaga(c1, c2);

        // Rajesh's money leaves his account, then flows through P1 then P2 (P2 is down).
        saga.pay("TXN-5001", "SAV2001", new BigDecimal("75000"));

        // A replay of the SAME transaction id after recovery → stored result, no double-debit.
        saga.pay("TXN-5001", "SAV2001", new BigDecimal("75000"));

        // Reconciliation verifies the ledger against both partners by transaction id.
        new Reconciler(c1, c2, saga).reconcile();
    }
}

// ─── saga/PaymentSaga.java ───  in-flight state + compensation + idempotency
class PaymentSaga {
    private static final Logger log = Logger.getLogger("XPay");
    private final PartnerChannel p1, p2;
    // durable in-flight + result store keyed by transaction id (idempotency)
    private final java.util.Map<String, String> state = new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.Map<String, BigDecimal> escrow = new java.util.concurrent.ConcurrentHashMap<>();

    PaymentSaga(PartnerChannel p1, PartnerChannel p2) { this.p1 = p1; this.p2 = p2; }

    void pay(String txnId, String sender, BigDecimal amount) throws InterruptedException {
        if ("COMPLETED".equals(state.get(txnId))) {         // IDEMPOTENT replay → stored result
            log.warning(() -> "TXN " + txnId + " already COMPLETED → return stored result (no double-debit)");
            return;
        }
        // STEP 0 — debit sender into durable in-flight ESCROW (money never 'lost')
        escrow.put(txnId, amount);
        state.put(txnId, "IN_FLIGHT");
        log.info(() -> "debited " + sender + " Rs." + amount + " into in-flight for " + txnId);

        // STEP 1 — leg via healthy partner 1
        if (!p1.send(txnId, amount)) { compensate(txnId, sender, "P1 leg failed"); return; }

        // STEP 2 — leg via partner 2 (DOWN). Retry idempotently until breaker recovers.
        boolean leg2 = false;
        for (int attempt = 1; attempt <= 6 && !leg2; attempt++) {
            leg2 = p2.send(txnId, amount);                  // same txnId each time (idempotent)
            if (!leg2) { log.warning("P2 leg attempt " + attempt + " failed, will retry"); Thread.sleep(1000); }
        }
        if (!leg2) { compensate(txnId, sender, "P2 permanently down"); return; }

        escrow.remove(txnId);
        state.put(txnId, "COMPLETED");
        log.info(() -> "TXN " + txnId + " COMPLETED across all partners");
    }

    private void compensate(String txnId, String sender, String reason) {
        // reverse completed legs + refund sender from escrow — money is made whole
        BigDecimal held = escrow.remove(txnId);
        if (held != null) log.severe(() -> "COMPENSATE " + txnId + " (" + reason + "): refund " + sender + " Rs." + held);
        p1.reverse(txnId); p2.reverse(txnId);
        state.put(txnId, "COMPENSATED");
    }
    String stateOf(String txnId) { return state.get(txnId); }
}

// ─── partner/PartnerChannel.java ───  BULKHEAD (own queue/consumer) + CIRCUIT BREAKER
class PartnerChannel {
    private static final Logger log = Logger.getLogger("XPay");
    private final ExternalPartner partner;
    private int failures = 0; private long openedAt = 0; private boolean open = false;
    // dedicated single-thread executor = this partner's isolated bulkhead
    private final java.util.concurrent.ExecutorService bulkhead =
            java.util.concurrent.Executors.newSingleThreadExecutor();

    PartnerChannel(ExternalPartner partner) { this.partner = partner; }

    boolean send(String txnId, BigDecimal amount) {
        if (open && System.currentTimeMillis() - openedAt < 5000) {
            log.warning(() -> partner.name() + " breaker OPEN → fail fast (" + txnId + ")");
            return false;                                    // fail fast, don't block
        }
        try {
            boolean ok = bulkhead.submit(() -> partner.process(txnId, amount)).get();  // isolated
            failures = 0; open = false;
            return ok;
        } catch (Exception e) {
            if (++failures >= 3) { open = true; openedAt = System.currentTimeMillis();
                log.severe(() -> partner.name() + " breaker TRIPPED after " + failures + " failures"); }
            return false;
        }
    }
    void reverse(String txnId) { partner.reverse(txnId); }
    String name() { return partner.name(); }
    boolean confirms(String txnId) { return partner.hasProcessed(txnId); }
    void shutdown() { bulkhead.shutdownNow(); }
}

// ─── partner/ExternalPartner.java ───  simulates a REST partner (NOT an XA resource!)
class ExternalPartner {
    private static final Logger log = Logger.getLogger("XPay");
    private final String name; private int failsRemaining;
    private final java.util.Set<String> processed = java.util.concurrent.ConcurrentHashMap.newKeySet();

    ExternalPartner(String name, int failsRemaining) { this.name = name; this.failsRemaining = failsRemaining; }

    boolean process(String txnId, BigDecimal amount) {
        if (processed.contains(txnId)) {                     // partner-side idempotency
            log.warning(() -> name + " already processed " + txnId + " → stored OK (no double-debit)");
            return true;
        }
        if (failsRemaining-- > 0) throw new RuntimeException(name + " DOWN");
        processed.add(txnId);
        log.info(() -> name + " processed leg for " + txnId + " Rs." + amount);
        return true;
    }
    void reverse(String txnId) { if (processed.remove(txnId)) log.warning(() -> name + " reversed " + txnId); }
    boolean hasProcessed(String txnId) { return processed.contains(txnId); }
    String name() { return name; }
}

// ─── recon/Reconciler.java ───  the final safety net
class Reconciler {
    private static final Logger log = Logger.getLogger("XPay");
    private final PartnerChannel p1, p2; private final PaymentSaga saga;
    Reconciler(PartnerChannel p1, PartnerChannel p2, PaymentSaga saga) { this.p1 = p1; this.p2 = p2; this.saga = saga; }
    void reconcile() {
        String txn = "TXN-5001";
        boolean agree = "COMPLETED".equals(saga.stateOf(txn)) == (p1.confirms(txn) && p2.confirms(txn));
        log.info(() -> "RECONCILE " + txn + ": ledger=" + saga.stateOf(txn)
                + " P1=" + p1.confirms(txn) + " P2=" + p2.confirms(txn) + " → consistent=" + agree);
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
